import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed (their claims that count added up; a person's OPEN or PENDING claims dated within a hold of theirs, or any once their retirement date is reached, not bound by a statement, do not, nor do deferred claims) and
 * due-total (the figures of those claims, each with its late charge, added up; n/a when their grade has no rate today and no counting claim
 * has a figure, kept or at the grade in force on its date; at most the sheet's cap), overdue-total (the figures, late charge included, of those claims that are overdue — open, their due-by plus
 * their grace (see LateCharge#lateFrom) before today — added up, skipping n/a; not capped), and the sheet's claimed-total, due-total and overdue-total (everyone's added up, skipping n/a; the due-total and
 * overdue-total leave out the single highest and the single lowest figure when three or more people have one).
 *
 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
 * person whose figures (claimed, due-total or overdue-total) moved (a person new to the sheet counts as moved), then
 * TOTALS when any of the sheet's three totals moved ({@link #record}), then ALERT, in list order, for every person
 * whose due-total went from at or below the sheet's alert threshold (or no due-total: n/a, or new to the sheet) to
 * above it (none while the threshold is off).
 */
@Service
public class Rollup {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Every person's figures on the sheet now, in list order (see PersonRepository#list). */
    public RollupBefore take(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean figured = false;
            for (Claim c : all) {
                if (c.personId() != person.id() || !ClaimDue.countsLive(c, person, today)) {
                    continue;
                }
                claimed = claimed.add(c.amount());
                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, late.rounding()), settings.floor(sheetId, c.date()));
                figured |= figure != null;
                if (figure != null) {
                    due = due.add(figure);
                    if (ClaimDue.isOpen(c) && late.lateFrom(c).isBefore(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a"
                    : SettingRepository.capped(due, cap).toPlainString();
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal,
                    overdue.toPlainString()));
        }
        return new RollupBefore(figures);
    }

    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
    public void record(String sheetId, String by, RollupBefore before) {
        Map<Long, Figures> after = take(sheetId).figures();
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.figures().get(e.getKey());
            Figures now = e.getValue();
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                        + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        String claimedBefore = claimedTotal(before.figures());
        String dueBefore = dueTotal(before.figures());
        String claimedAfter = claimedTotal(after);
        String dueAfter = dueTotal(after);
        String overdueBefore = overdueTotal(before.figures());
        String overdueAfter = overdueTotal(after);
        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)
                || !Objects.equals(overdueBefore, overdueAfter)) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
                    + dueAfter + " overdue-total=" + overdueAfter);
        }
        alert(sheetId, by, before.figures(), after);
    }

    /** Writes ALERT, in list order, for every person whose due-total went from at or below the sheet's alert threshold
     *  (or no due-total) before to above it now. */
    private void alert(String sheetId, String by, Map<Long, Figures> before, Map<Long, Figures> after) {
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold == null) {
            return;
        }
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.get(e.getKey());
            Figures now = e.getValue();
            if (above(now, threshold) && (was == null || !above(was, threshold))) {
                audit.record("ALERT sheet=" + sheetId + " by=" + by + " name=" + now.name() + " due-total="
                        + now.dueTotal());
            }
        }
    }

    private static boolean above(Figures figures, BigDecimal threshold) {
        return !figures.dueTotal().equals("n/a") && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
    }

    /** Writes ROLLUP for every person on the sheet, in list order, then TOTALS, then ALERT for those above the alert
     *  threshold: the figures of a sheet just made. */
    public void recordAll(String sheetId, String by) {
        Map<Long, Figures> now = take(sheetId).figures();
        for (Figures f : now.values()) {
            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + f.name() + " claimed=" + f.claimed()
                    + " due-total=" + f.dueTotal() + " overdue-total=" + f.overdueTotal());
        }
        audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedTotal(now) + " due-total="
                + dueTotal(now) + " overdue-total=" + overdueTotal(now));
        alert(sheetId, by, Map.of(), now);
    }

    private static String claimedTotal(Map<Long, Figures> figures) {
        return figures.values().stream().map((f) -> new BigDecimal(f.claimed()))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }

    private static String overdueTotal(Map<Long, Figures> figures) {
        return trimmedTotal(figures.values().stream().map(Figures::overdueTotal).toList());
    }

    private static String dueTotal(Map<Long, Figures> figures) {
        return trimmedTotal(figures.values().stream().map(Figures::dueTotal).toList());
    }

          <li key={i} data-testid="claim-comments-line">
            {commentLine(m)}
          </li>
        ))}
      </ol>
    </li>
  );
}

/** A person's claimed, and their claims (newest first) with the form that adds one or saves the one
 *  being edited. A blank date takes the sheet's entry date, else its today (the server applies it). */
function PersonClaims({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId).data;
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const mine = claims.data?.filter((c) => c.personId === person.id) ?? [];
  const [editingId, setEditingId] = useState<number | undefined>(undefined);
  const [values, setValues] = useState<Values>(EMPTY);
  const unlock = useMutation({
    mutationFn: (id: number) => putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${id}/unlock`, { by: user }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: ({ id, ...v }: Values & { id?: number }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}`;
      const body = { ...v, by: user };
      return id === undefined
        ? postJson<Claim>(`${base}/people/${person.id}/claims`, body)
        : putJson<Claim>(`${base}/claims/${id}`, body);
    },
    onSuccess: () => {
      setValues(EMPTY);
      setEditingId(undefined);
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  // A DRAFT claim with the chosen template's amount and note as they are now, no date: added by the claim form's rules,
  // its refusal shown in the form's error.
  const templates = useTemplates(sheetId).data ?? [];
  const [template, setTemplate] = useState('');
  const fromTemplate = useMutation({
    mutationFn: (name: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/template-claims`, { template: name, by: user }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  const change = (v: Partial<Values>) => {
    setValues((was) => ({ ...was, ...v }));
    save.reset();
    fromTemplate.reset();
  };
  const openEditor = (c: Claim) => {
    save.reset();
    fromTemplate.reset();
    if (editingId !== undefined && editingId !== c.id) unlock.mutate(editingId);
    setValues({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: c.tags.join(', ') });
    setEditingId(c.id);
  };
  const cancel = () => {
    save.reset();
    fromTemplate.reset();
    if (editingId !== undefined) unlock.mutate(editingId);
    setValues(EMPTY);
    setEditingId(undefined);
  };

  // The editor of a claim the user still holds (its lock outlived a reload of the sheet) opens again once the claims
  // are read fresh, so it can be saved or cancelled.
  const restored = useRef(false);
  useEffect(() => {
    if (restored.current || claims.data === undefined || claims.isFetching) return;
    restored.current = true;
    const held = mine.find((c) => c.lockedBy === user && c.status === 'DRAFT');
    if (held !== undefined && editingId === undefined) openEditor(held);
  });

  return (
    <>
      <td data-testid="person-claimed">{total(live(mine, [person], today))}</td>
      <td>
        <form
          data-testid="claim-form"
          onSubmit={(e) => {
            e.preventDefault();
            if (!submit.begin()) return;
            save.reset();
            fromTemplate.reset();
            save.mutate({ ...values, id: editingId });
          }}
        >
          <input
            data-testid="claim-form-amount"
            placeholder="Amount"
            inputMode="decimal"
            value={values.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />{' '}
          <input type="date" data-testid="claim-form-date" value={values.date} onChange={(e) => change({ date: e.target.value })} />{' '}
          <input data-testid="claim-form-note" placeholder="Note" value={values.note} onChange={(e) => change({ note: e.target.value })} />{' '}
          <input
            data-testid="claim-form-corrects"
            placeholder="Corrects no."
            inputMode="numeric"
            value={values.corrects}
            onChange={(e) => change({ corrects: e.target.value })}
          />{' '}
          <input data-testid="claim-form-ref" placeholder="Reference" value={values.ref} onChange={(e) => change({ ref: e.target.value })} />{' '}
          <input data-testid="claim-form-tags" placeholder="Tags, comma separated" value={values.tags} onChange={(e) => change({ tags: e.target.value })} />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editingId === undefined ? 'Add claim' : 'Save claim'}
          </button>
          <select
            data-testid="claim-template-select"
            value={template}
            onChange={(e) => {
              setTemplate(e.target.value);
              save.reset();
              fromTemplate.reset();
            }}
          >
            <option value="">Template…</option>
            {templates.map((t) => (
              <option key={t.name} value={t.name}>
                {t.name}
              </option>
            ))}
          </select>{' '}
          <button
            type="button"
            data-testid="claim-template-add"
            disabled={fromTemplate.isPending}
            onClick={() => {
              if (!submit.begin()) return;
              save.reset();
              fromTemplate.reset();
              fromTemplate.mutate(template);
            }}
          >
            Add from template
          </button>
          {(save.isError || fromTemplate.isError) && (
            <span data-testid="claim-form-error">
              The amount must have up to two decimals, and be 0.00 or more unless it corrects, by number, a settled claim of this person; its due-by not inside a closed period, the date not after the person's retirement date, the reference not one already used on the sheet, and only a draft claim can be edited.
            </span>
          )}
        </form>
        <ul data-testid="claim-list">
          {mine.map((c) => (
            <ClaimRow
              key={c.id}
              sheetId={sheetId}
              user={user}
              claim={c}
              rate={rateFor(rates, gradeOn(person, c.date), c.date)}
              floor={floor}
              editing={editingId === c.id}
              onEdit={() => openEditor(c)}
              onCancel={cancel}
            />
          ))}
        </ul>
      </td>
    </>
  );
}

/** The sheet's claimed-total: everyone's claimed (OPEN, PENDING and SETTLED claims, but no OPEN or PENDING ones dated within a hold of their person, or of one whose retirement date is reached, and not bound by a statement) added up. */
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const today = useSheetToday(sheetId);
  return (
    <p>
      Claimed total <span data-testid="rollup-claimed-total">{total(live(claims.data ?? [], people.data, today))}</span>
      {claims.isError && <span data-testid="claims-load-error"> Could not load claims.</span>}
    </p>
  );
}

